(()=>{const en=()=>window.ofLang==='en',t=(fa,eng)=>en()?eng:fa,num=n=>new Intl.NumberFormat(en()?'en-US':'fa-IR').format(n),money=n=>'$'+new Intl.NumberFormat('en-US').format(n);let mode='plans';
function details(){const p=presets[currentPreset],size=currentSize;const names={start:['شروع','Starter'],standard:['استاندارد','Standard'],single:['تک‌مرحله‌ای','One phase']};const name=names[currentPreset][en()?1:0];const items=[[t('هدف مرحلهٔ اول','Phase 1 target'),p.phases===2?'5% · '+money(size*.05):'10% · '+money(size*.1)],[t('هدف مرحلهٔ دوم','Phase 2 target'),p.phases===2?'10% · '+money(size*.1):'—'],[t('حد زیان روزانه','Daily loss limit'),'3% · '+money(size*.03)],[t('افت کل مجاز','Maximum loss'),p.loss+'% · '+money(size*p.loss/100)],[t('حداقل روز معاملاتی','Minimum trading days'),t('ندارد · نمونه','None · sample')],[t('مهلت ارزیابی','Time limit'),t('بدون محدودیت','Unlimited')]];const funded=[[t('ماهیت حساب','Account type'),t('شبیه‌سازی‌شده','Simulated')],[t('سهم معامله‌گر','Trader reward share'),p.split+'%'],[t('سقف برداشت کل','Lifetime payout cap'),p.cap?money(size*p.cap/100):t('بدون سقف','No cap')],[t('زمان و حداقل برداشت','Payout timing & minimum'),t('طبق قرارداد نهایی','Subject to final agreement')],[t('هدف سود پس از قبولی','Target after passing'),t('ندارد · نمونه','None · sample')],[t('شرایط نقض حساب','Account breach'),t('رسیدن به حد زیان','Touching a loss limit')]];const dl=data=>data.map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('');document.querySelector('#evaluation-rules').innerHTML=dl(items);document.querySelector('#funded-rules').innerHTML=dl(funded);document.querySelector('#challenge-order').innerHTML=`<p>${name} · ${money(size)}</p><p>${t('هزینهٔ یک‌باره','One-time fee')}: <strong>${money(p.prices[size])}</strong></p><p>${t('بدون پرداخت واقعی در این نسخه','No real payment in this version')}</p>`;
const compare=document.querySelector('#challenge-comparison');compare.hidden=mode!=='compare';compare.className='compare-table';compare.innerHTML=`<table><thead><tr><th>${t('ویژگی','Feature')}</th>${Object.keys(presets).map(k=>`<th>${names[k][en()?1:0]}</th>`).join('')}</tr></thead><tbody>${[[t('مراحل','Phases'),...Object.values(presets).map(p=>p.phases)],[t('هدف سود','Profit target'),'5% + 10%','5% + 10%','10%'],[t('زیان روزانه','Daily loss'),'3%','3%','3%'],[t('افت کل','Maximum loss'),'3%','6%','3%'],[t('سهم معامله‌گر','Trader share'),'60%','80%','80%'],[t('حداقل روز','Minimum days'),'0','0','0'],[t('اندازه‌های حساب','Account sizes'),'5k / 10k / 20k','10k / 50k / 100k','10k / 50k / 100k'],[t('قیمت در اندازهٔ انتخابی','Fee for selected size'),...Object.values(presets).map(p=>p.prices[size]?money(p.prices[size]):'—')]].map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
document.querySelectorAll('[data-preset]').forEach(b=>b.addEventListener('click',details));document.querySelector('#builder-sizes').addEventListener('click',details);document.querySelectorAll('[data-challenge-view]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.challengeView;document.querySelectorAll('[data-challenge-view]').forEach(x=>x.classList.toggle('active',x===b));details()}));document.querySelector('#detail-review').addEventListener('click',()=>{openReview();window.ofTranslate?.()});addEventListener('of-language',()=>{details();age()});function age(){const now=new Date();let years=now.getUTCFullYear()-2026,months=now.getUTCMonth()-8;if(months<0){years--;months+=12}document.querySelector('#activity-age').textContent=`${String(Math.max(0,years)).padStart(2,'0')}y ${String(months).padStart(2,'0')}m`;};age();details();setInterval(age,3600000);})();
